#!/usr/bin/env python
"""gen_rust_tables.py - docs/specs/data/*.tsv -> crates/puce-z80/src/tables/*.rs (generated, do not edit by hand).
Run from the repo root:  python docs/tools/gen_rust_tables.py
Needs the types of crates/puce-z80/src/engine/plan.rs (task E02-01): Kind, Addr, Reg, Tok::new (const fn), Plan.
"""
import re, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
DATA = ROOT / "docs" / "specs" / "data"
OUT = ROOT / "crates" / "puce-z80" / "src" / "tables"
ADDR = {'PC+': 'PcInc', 'SP': 'Sp', 'SP+': 'SpInc', 'SP+1': 'SpPlus1', '-SP': 'DecSp', 'HL': 'Hl', 'BC': 'Bc', 'DE': 'De',
        'NN': 'Nn', 'NN+1': 'NnPlus1', 'XY': 'Xy', 'AN': 'An'}
KIND = {'F': 'F', 'R': 'R', 'W': 'W', 'N': 'N', 'O': 'O', 'I': 'I', 'X': 'X'}
TOK = re.compile(r'^(\?)?([FRWNOIX])(\d+)(?::([A-Z0-9+\-]+)([<>])([A-Z]+))?$')

def tok(t):
    m = TOK.match(t)
    if not m:
        raise SystemExit("bad token %r" % t)
    cond, k, n, addr, _dir, reg = m.groups()
    a = 'Addr::None' if addr is None else 'Addr::' + ADDR[addr]
    r = 'Reg::None' if reg is None else 'Reg::' + reg
    return "Tok::new(Kind::%s, %s, %s, %s, %s)" % (KIND[k], n, a, r, 'true' if cond else 'false')

def gen(name, const):
    rows = (DATA / (name + ".tsv")).read_text(encoding="utf-8").splitlines()[1:]
    plans, ts = [], []
    for r in rows:
        c = r.split("\t")
        if c[1] in ('-', 'prefix'):
            plans.append("    &[],")
            ts.append("(0, 0)")
        else:
            plans.append("    &[%s]," % ", ".join(tok(t) for t in c[3].split()))
            ts.append("(%s, %s)" % (c[4], c[5]))
    assert len(plans) == 256, name
    s = ["// GENERATED by docs/tools/gen_rust_tables.py from docs/specs/data/%s.tsv - do not edit." % name,
         "use crate::engine::plan::{Addr, Kind, Plan, Reg, Tok};", "",
         "pub static %s: [Plan; 256] = [" % const] + plans + ["];", "",
         "/// (t_min, t_max) per opcode, from the TSV (used by tests).",
         "pub static %s_T: [(u8, u8); 256] = [" % const] + ["    %s," % t for t in ts] + ["];", ""]
    (OUT / (name + ".rs")).write_text("\n".join(s), encoding="ascii", newline="\n")

def gen_mnem():
    out = ["// GENERATED by docs/tools/gen_rust_tables.py from docs/specs/data/*.tsv - do not edit.",
           "// Mnemonic templates: nn = 16-bit immediate, n = 8-bit immediate, d = signed displacement, e = relative target.", ""]
    for name, const in (('main', 'MAIN'), ('cb', 'CB'), ('ed', 'ED'), ('ddfd', 'DDFD'), ('ddcb', 'DDCB')):
        rows = (DATA / (name + ".tsv")).read_text(encoding="utf-8").splitlines()[1:]
        out.append("pub static MNEM_%s: [&str; 256] = [" % const)
        for r in rows:
            m = r.split("\t")[1]
            out.append('    "%s",' % m.replace('"', ''))
        out.append("];")
        out.append("")
    (OUT / "mnem.rs").write_text("\n".join(out), encoding="ascii", newline="\n")

if __name__ == "__main__":
    OUT.mkdir(parents=True, exist_ok=True)
    for n, c in (('main', 'MAIN'), ('cb', 'CB'), ('ed', 'ED'), ('ddfd', 'DDFD'), ('ddcb', 'DDCB')):
        gen(n, c)
    gen_mnem()
    (OUT / "mod.rs").write_text("// GENERATED - declares the generated tables.\npub mod main;\npub mod cb;\npub mod ed;\npub mod ddfd;\npub mod ddcb;\n#[cfg(feature = \"disasm\")]\npub mod mnem;\n", encoding="ascii", newline="\n")
    print("tables written to", OUT)
